// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 amount1, uint256 amount2, address actor) public {
        vm.assume(amount1 <= VALUE_CAP);
        vm.assume(amount2 <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(amount1 <= address(this).balance / 2 && amount2 <= address(this).balance / 2);
        vm.deal(actor, amount1 + amount2);

        vm.startPrank(actor);
        c.Put{value: amount1}(0);
        uint256 afterFirst = __invmut_c_Acc_balance(actor);
        c.Put{value: amount2}(0);
        vm.stopPrank();

        assertTrue(
            afterFirst == amount1 && __invmut_c_Acc_balance(actor) == amount1 + amount2,
            "Put must accumulate deposits into the sender's balance"
        );
    }

    function __invmut_c_Acc_balance(address __k) internal view returns (uint256) {
        (, uint256 _v1) = c.Acc(__k);
        return _v1;
    }
}
